sys_variable_value.value:
/**
 * Thin bridge: calls bfd_ReroutingEngine.evaluateReroute(caseSysId) and
 * flattens the structured result onto the action outputs.
 *
 * Boolean-ish outputs are emitted as the strings 'true' / 'false' so that
 * bfd_flow_risk_routing can branch on them directly, matching the convention
 * used by the other SafeTrace custom actions.
 */
(function execute(inputs, outputs) {
    var result = new bfd_ReroutingEngine().evaluateReroute(inputs.caseSysId) || {};

    outputs.rerouted = result.rerouted ? 'true' : 'false';
    outputs.humanOwned = result.humanOwned ? 'true' : 'false';
    outputs.fromTeam = result.fromTeam || '';
    outputs.toTeam = result.toTeam || '';
    outputs.fromGroup = result.fromGroup || '';
    outputs.toGroup = result.toGroup || '';
    outputs.fromPriority = result.fromPriority || '';
    outputs.toPriority = result.toPriority || '';
    outputs.matchedRuleName = result.matchedRuleName || '';
    outputs.slaHours = result.slaHours || 0;
    outputs.reason = result.reason || '';
})(inputs, outputs);

